// Backend Bundle JavaScript with comprehensive jQuery support
(function() {
    'use strict';
    
    console.log('🔧 Backend bundle loading...');
    
    // Wait for jQuery to be available
    function waitForjQuery(callback) {
        if (typeof window.jQuery !== 'undefined' && typeof window.$ !== 'undefined') {
            callback();
        } else {
            setTimeout(function() { waitForjQuery(callback); }, 50);
        }
    }
    
    function initBackendBundle() {
        console.log('🎯 Initializing backend bundle with jQuery support...');
        var $ = window.jQuery;
        
        // Comprehensive Popover fallback
        if (typeof $.fn.popover === 'undefined') {
            $.fn.popover = function(options) {
                console.log('✓ Popover fallback initialized');
                return this.each(function() {
                    var el = this;
                    var opts = options || {};
                    
                    // Handle different trigger types
                    var trigger = opts.trigger || $(el).data('trigger') || 'click';
                    
                    var showPopover = function() {
                        var content = opts.content || $(el).data('content') || 'Popover content';
                        var title = opts.title || $(el).data('title') || '';
                        
                        // Remove existing popovers
                        $('.popover-fallback').remove();
                        
                        // Create popover element
                        var popover = $('<div class="popover popover-fallback bs-popover-top show" role="tooltip">');
                        if (title) {
                            popover.append('<div class="arrow"></div><h3 class="popover-header">' + title + '</h3><div class="popover-body">' + content + '</div>');
                        } else {
                            popover.append('<div class="arrow"></div><div class="popover-body">' + content + '</div>');
                        }
                        
                        // Style the popover
                        popover.css({
                            position: 'absolute',
                            zIndex: 1060,
                            maxWidth: '276px',
                            padding: '1px',
                            backgroundColor: '#fff',
                            border: '1px solid rgba(0,0,0,.2)',
                            borderRadius: '0.375rem',
                            boxShadow: '0 0.5rem 1rem rgba(0,0,0,.15)'
                        });
                        
                        $('body').append(popover);
                        
                        // Position the popover
                        var rect = el.getBoundingClientRect();
                        var popoverHeight = popover.outerHeight();
                        var popoverWidth = popover.outerWidth();
                        
                        popover.css({
                            top: rect.top - popoverHeight - 8 + window.scrollY,
                            left: rect.left + (rect.width / 2) - (popoverWidth / 2) + window.scrollX
                        });
                        
                        // Auto-hide after delay
                        setTimeout(function() {
                            popover.fadeOut(function() {
                                popover.remove();
                            });
                        }, opts.delay || 3000);
                    };
                    
                    var hidePopover = function() {
                        $('.popover-fallback').fadeOut(function() {
                            $(this).remove();
                        });
                    };
                    
                    // Bind events based on trigger
                    if (trigger === 'hover' || trigger === 'mouseenter') {
                        $(el).on('mouseenter', showPopover).on('mouseleave', hidePopover);
                    } else if (trigger === 'focus') {
                        $(el).on('focus', showPopover).on('blur', hidePopover);
                    } else { // default to click
                        $(el).on('click', function(e) {
                            e.preventDefault();
                            showPopover();
                        });
                    }
                    
                    // Store methods for programmatic control
                    $(el).data('bs.popover', {
                        show: showPopover,
                        hide: hidePopover,
                        toggle: function() {
                            if ($('.popover-fallback').length) {
                                hidePopover();
                            } else {
                                showPopover();
                            }
                        }
                    });
                });
            };
        }
        
        // Tooltip fallback
        if (typeof $.fn.tooltip === 'undefined') {
            $.fn.tooltip = function(options) {
                console.log('✓ Tooltip fallback initialized');
                return this.each(function() {
                    var el = this;
                    var opts = options || {};
                    var title = opts.title || $(el).attr('title') || $(el).data('title');
                    
                    if (title) {
                        $(el).on('mouseenter', function() {
                            var tooltip = $('<div class="tooltip-fallback bs-tooltip-top show">' + title + '</div>');
                            tooltip.css({
                                position: 'absolute',
                                zIndex: 1070,
                                padding: '2px 8px',
                                backgroundColor: '#000',
                                color: '#fff',
                                borderRadius: '4px',
                                fontSize: '12px',
                                whiteSpace: 'nowrap'
                            });
                            
                            $('body').append(tooltip);
                            
                            var rect = el.getBoundingClientRect();
                            tooltip.css({
                                top: rect.top - tooltip.outerHeight() - 5 + window.scrollY,
                                left: rect.left + (rect.width / 2) - (tooltip.outerWidth() / 2) + window.scrollX
                            });
                            
                            $(el).data('tooltip-element', tooltip);
                        }).on('mouseleave', function() {
                            var tooltip = $(el).data('tooltip-element');
                            if (tooltip) {
                                tooltip.remove();
                            }
                        });
                    }
                });
            };
        }
        
        // Modal fallback
        if (typeof $.fn.modal === 'undefined') {
            $.fn.modal = function(action) {
                return this.each(function() {
                    var $modal = $(this);
                    
                    if (action === 'show') {
                        $modal.show().addClass('show');
                        $('body').addClass('modal-open');
                        
                        if (!$('.modal-backdrop').length) {
                            $('<div class="modal-backdrop fade show"></div>').appendTo('body');
                        }
                    } else if (action === 'hide') {
                        $modal.removeClass('show').hide();
                        $('body').removeClass('modal-open');
                        $('.modal-backdrop').remove();
                    } else if (action === 'toggle') {
                        if ($modal.hasClass('show')) {
                            $modal.modal('hide');
                        } else {
                            $modal.modal('show');
                        }
                    }
                });
            };
        }
        
        // Dropdown fallback
        if (typeof $.fn.dropdown === 'undefined') {
            $.fn.dropdown = function(action) {
                return this.each(function() {
                    var $dropdown = $(this);
                    var $menu = $dropdown.next('.dropdown-menu');
                    
                    if (action === 'toggle') {
                        $menu.toggle();
                        $dropdown.parent().toggleClass('show');
                    } else if (action === 'show') {
                        $menu.show();
                        $dropdown.parent().addClass('show');
                    } else if (action === 'hide') {
                        $menu.hide();
                        $dropdown.parent().removeClass('show');
                    }
                });
            };
        }
        
        // Collapse fallback
        if (typeof $.fn.collapse === 'undefined') {
            $.fn.collapse = function(action) {
                return this.each(function() {
                    var $element = $(this);
                    
                    if (action === 'show') {
                        $element.slideDown().addClass('show');
                    } else if (action === 'hide') {
                        $element.slideUp().removeClass('show');
                    } else if (action === 'toggle') {
                        if ($element.hasClass('show')) {
                            $element.collapse('hide');
                        } else {
                            $element.collapse('show');
                        }
                    }
                });
            };
        }
        
        console.log('✅ Backend bundle initialization complete');
        
        // Trigger a custom event to notify other scripts that backend bundle is ready
        if (typeof window.CustomEvent !== 'undefined') {
            var event = new CustomEvent('backendBundleReady', { detail: { $ : $ } });
            window.dispatchEvent(event);
        }
        
        // Set a flag for other scripts to check
        window.backendBundleReady = true;
    }
    
    // Initialize when jQuery is ready (immediately, not waiting for DOM)
    waitForjQuery(function() {
        console.log('✅ jQuery detected, initializing backend bundle immediately...');
        initBackendBundle();
    });
    
})();
